// The logic for these tests is pretty ridiculous, but this is MINUTES more
// efficient than plugging these replays into an actual <Game> instance.

import assert from 'node:assert/strict'
import { describe, it } from 'node:test'

import { getLogic, type Enemy } from '../../../src/components/Game/logic.ts'
import type { GameState } from '../../../src/components/Game/logic.ts'
import { hatetris, hatetrisMild, brz } from '../../../src/components/Game/Game.tsx'
import hatetrisRotationSystem from '../../../src/rotation-systems/hatetris-rotation-system.ts'
import hatetrisReplayCodec from '../../../src/replay-codecs/hatetris-replay-codec.ts'

type Runs = ReadonlyArray<{
  aiName: string
  enemy: Enemy
  aiRuns: ReadonlyArray<{
    name: string
    expectedScore: number
    replay: string
  }>
}>

const logic = getLogic({
  bar: 4,
  replayTimeout: 0,
  copyTimeout: 0,
  rotationSystem: hatetrisRotationSystem,
  wellDepth: 20,
  wellWidth: 10
})

describe('logic', () => {
  describe('check known replays', function () {
    const runs: Runs = [
      {
        aiName: 'HATETRIS',
        enemy: hatetris,
        aiRuns: [
          {
            name: 'qntm',
            expectedScore: 0,
            replay: 'DDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDDD'
          },
          {
            name: 'Atypical',
            expectedScore: 11,
            replay: ''
          },
          {
            name: 'SDA (1)',
            expectedScore: 17,
            replay: ''
          },
          {
            name: 'SDA (2)',
            expectedScore: 20,
            replay: ''
          },
          {
            name: 'Ivenris',
            expectedScore: 22,
            replay: ''
          },
          {
            name: 'SDA (3)',
            expectedScore: 28,
            replay: ''
          },
          {
            name: 'Deasuke',
            expectedScore: 30,
            replay: ''
          },
          {
            name: 'chromeyhex',
            expectedScore: 31,
            replay: ''
          },
          {
            name: 'knewjade (1)',
            expectedScore: 32,
            replay: ''
          },
          {
            name: 'knewjade (2)',
            expectedScore: 34,
            replay: ''
          },
          {
            name: 'knewjade (3)',
            expectedScore: 41,
            replay: ''
          },
          {
            name: 'knewjade (4)',
            expectedScore: 66,
            replay: ''
          },
          {
            name: 'David & Felipe (1)',
            expectedScore: 86,
            replay: ''
          },
          {
            name: 'David & Felipe (2)',
            expectedScore: 148,
            replay: ''
          },
          {
            name: 'David & Felipe (3)',
            expectedScore: 152,
            replay: ''
          },
          {
            name: 'Tim (1)',
            expectedScore: 157,
            replay: ''
          },
          {
            name: 'Tim (2)',
            expectedScore: 232,
            replay: ''
          },
          {
            name: 'knewjade (5)',
            expectedScore: 289,
            replay: ''
          },
          {
            name: 'David & Felipe (4)',
            expectedScore: 302,
            replay: ''
          },
          {
            name: 'David & Felipe (5)',
            expectedScore: 366,
            replay: ''
          },
          {
            name: 'David & Felipe (6)',
            expectedScore: 3711,
            replay: ''
          },
          {
            name: 'skidikipopop',
            expectedScore: 4178,
            replay: ''
          }
        ]
      },
      {
        aiName: 'HATETRIS',
        enemy: hatetris,
        aiRuns: [
          {
            // Source https://gist.githubusercontent.com/knewjade/00f380b6e82f6212ecacd7bb4322701e/raw/6839b881c6a72149e51262d34623ff9b9a5d8134/replay_fired_leadsIntoCycle.txt
            name: 'knewjade loop basis',
            expectedScore: 107,
            replay: ''
          }
        ]
      },
      {
        // Loop replays consist of two components, the "setup" which gets us to a particular well,
        // followed by the "cycle" which takes us back to that precise well again.
        // These work only with HATETRIS Mild - O.G. HATETRIS detects and prevents well repetition.
        aiName: 'HATETRIS Mild',
        enemy: hatetrisMild,
        aiRuns: [
          {
            /*
              Repeated well is:
              [0,0,0,0,0,0,128,384,256,897,963,999,963,993,963,999,1011,1015,559,502]
              ..........
              ..........
              ..........
              ..........
              ..........
              ..........
              .......#..
              .......##.
              ........#.
              #......###
              ##....####
              ###..#####
              ##....####
              #....#####
              ##....####
              ###..#####
              ##..######
              ###.######
              ####.#...#
              .##.#####.
            */
            name: 'knewjade loop',
            expectedScore: 95 + 10 * 7, // ranking = 105
            replay: (
              '' +
              ''.repeat(7)
            )
          },
          {
            name: 'Tim loop',
            expectedScore: 68 + 16 * 11, // ranking = 84
            replay: (
              '' +
              ''.repeat(11)
            )
          },
          {
            name: 'David & Felipe loop',
            expectedScore: 10 + 10 * 6, // ranking = 20
            replay: (
              '' + 
              ''.repeat(6)
            )
          },
          {
            name: 'David & Felipe loop 2',
            expectedScore: 9 + 10 * 3, // ranking = 19
            replay: (
              '' +
              ''.repeat(3)
            )
          },
          {
            name: 'David & Felipe loop 3',
            expectedScore: 7 + 10 * 4, // ranking = 17
            replay: (
              '' +
              ''.repeat(4)
            )
          },
          {
            name: 'skidikipopop loop',
            expectedScore: 4 + 10 * 6, // ranking = 14
            replay: (
              '' +
              ''.repeat(6)
            )
          }
        ]
      },
      {
        aiName: 'Brzustowski',
        enemy: brz,
        aiRuns: [
          {
            name: 'demo',
            expectedScore: 55,
            replay: ''
          }
        ]
      }
    ]

    runs.forEach(({ aiName, enemy, aiRuns }) => {
      describe(aiName, () => {
        aiRuns.forEach(({ name, expectedScore, replay: str }) => {
          it(name, async () => {
            const replay = hatetrisReplayCodec.decode(str)

            const firstState: GameState = {
              customAiCode: '',
              displayEnemy: false,
              enemy,
              error: null,
              mode: 'REPLAYING',
              wellStateId: -1,
              wellStates: [],
              replay,
              replayCopiedTimeoutId: undefined,
              replayTimeoutId: undefined
            }

            firstState.wellStates.push(await logic.getFirstWellState(firstState))
            firstState.wellStateId++

            let state = firstState
            for (const move of replay) {
              if (state.mode === 'GAME_OVER') {
                throw Error('replay too long')
              } else {
                state = {
                  ...state,
                  ...await logic.handleMove(state, move)
                }
              }
            }

            assert.equal(state.error, null)
            assert.equal(state.wellStates[state.wellStateId].core.score,
              expectedScore)
          })
        })
      })
    })
  })
})
